# Flattening Mesh Surfaces to 2D in C

First, an honest caveat, because it shapes the design: **no flat map can preserve both distances and areas exactly** for a curved surface (Gauss's *Theorema Egregium* — this is why every world map compromises). What we can do is minimize distortion, which is what all mesh parameterization does. The standard, well-behaved choice is **LSCM (Least-Squares Conformal Maps)**, which preserves angles well and keeps area distortion bounded; if area is your priority, swap the weights as noted below.

The program below:

1. Reads a Wavefront OBJ (triangles assumed; quads are split).
2. Groups triangles into **connected patches** ("surfaces") by shared vertices.
3. Flattens each patch independently with LSCM (a sparse least-squares solve).
4. Writes one **SVG page per patch**, scaled to fit.

Each patch is independent, so overlap across pages is irrelevant, as you said.

```c
/* flatten.c
 * Usage: ./flatten model.obj outdir
 * Writes outdir/patch_000.svg, patch_001.svg, ...
 *
 * Build (Linux/POSIX):  cc -O2 -o flatten flatten.c -lm
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <sys/stat.h>
#include <sys/types.h>

#define MAXV 200000
#define MAXT 400000

typedef struct { double x, y, z; } Vec3;
typedef struct { int a, b, c; } Tri;

static Vec3  V[MAXV];  static int nV;
static Tri   T[MAXT];  static int nT;

/* per-patch data */
static int *triPatch;      /* patch id per triangle   */
static int *vertPatch;     /* patch id per vertex, -1 unknown */
static int  nPatches;

/* ---- tiny linear algebra ---- */
static Vec3 sub3(Vec3 a, Vec3 b){ return (Vec3){a.x-b.x,a.y-b.y,a.z-b.z}; }
static double dot3(Vec3 a, Vec3 b){ return a.x*b.x+a.y*b.y+a.z*b.z; }
static Vec3 cross3(Vec3 a, Vec3 b){
    return (Vec3){a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x};
}
static double norm3(Vec3 a){ return sqrt(dot3(a,a)); }

/* ---------------- OBJ loading ---------------- */
static void load_obj(const char *path)
{
    FILE *f = fopen(path, "r");
    if (!f){ fprintf(stderr,"cannot open %s\n",path); exit(1); }
    char line[4096];
    while (fgets(line,sizeof line,f)){
        if (line[0]=='v' && (line[1]==' '||line[1]=='\t')){
            Vec3 p; sscanf(line+2,"%lf %lf %lf",&p.x,&p.y,&p.z);
            if (nV<MAXV) V[nV++]=p;
        } else if (line[0]=='f'){
            int idx[8], n=0; char *p=line+2;
            while (sscanf(p,"%d",&idx[n])==1){
                n++;
                while (*p && *p!=' ') p++;
                while (*p==' ') p++;
                if (!*p) break;
            }
            /* OBJ is 1-based; negative = relative (rare here, ignored) */
            for (int i=0;i<n;i++) idx[i]--;
            for (int i=2;i<n && nT<MAXT;i++){
                T[nT++] = (Tri){idx[0], idx[i-1], idx[i]};
            }
        }
    }
    fclose(f);
}

/* ---------------- patch segmentation ----------------
 * Union-find over vertices; a patch = a connected component
 * of triangles via shared vertices. */
static int uf[MAXV];
static int find(int x){ while (uf[x]!=x){ uf[x]=uf[uf[x]]; x=uf[x]; } return x; }
static void uni(int a,int b){ a=find(a); b=find(b); if(a!=b) uf[a]=b; }

static void build_patches(void)
{
    for (int i=0;i<nV;i++) uf[i]=i;
    for (int t=0;t<nT;t++){ uni(T[t].a,T[t].b); uni(T[t].a,T[t].c); }

    vertPatch = malloc(nV*sizeof(int));
    for (int i=0;i<nV;i++) vertPatch[i]=-1;
    triPatch  = malloc(nT*sizeof(int));

    /* assign each root a patch id */
    int *rootId = malloc(nV*sizeof(int));
    for (int i=0;i<nV;i++) rootId[i]=-1;
    nPatches=0;
    for (int i=0;i<nV;i++){
        int r=find(i);
        if (rootId[r]==-1) rootId[r]=nPatches++;
        vertPatch[i]=rootId[r];
    }
    for (int t=0;t<nT;t++) triPatch[t]=vertPatch[T[t].a];
    free(rootId);
}

/* ---------------- LSCM per patch ----------------
 * For triangle (i,j,k) with 3D local coords (x,y), LSCM minimizes
 * sum over triangles of  W * || (a u' + b v') - rot90(a u + b v) ||^2
 * in the two complex unknowns per vertex.  We build the real
 * normal equations A^T A x = A^T b with two vertices pinned,
 * and solve with a dense Cholesky (patches are assumed modest;
 * for huge patches swap in a sparse solver).
 */
typedef struct { int n;              /* vertices in patch            */
                 int *vidx;          /* global index of each local   */
                 int *lidx;          /* local index per global vert  */
                 double *ATA;        /* 4n x 4n normal matrix        */
                 double *ATb;        /* 4n rhs                       */
} LS;

static void addATA(LS *s,int r,int c,double v){ s->ATA[r*s->n*4+c]+=v; }

static void accumulate_tri(LS *s, int t)
{
    int i=T[t].a, j=T[t].b, k=T[t].c;
    Vec3 p0=V[i], p1=V[j], p2=V[k];
    /* local 2D frame: x along edge01, y in triangle plane */
    Vec3 e1=sub3(p1,p0); Vec3 e2=sub3(p2,p0);
    Vec3 n=cross3(e1,e2); double len=norm3(n); if(len<1e-14) return;
    n.x/=len; n.y/=len; n.z/=len;
    Vec3 t1=e1; double l1=norm3(t1); t1.x/=l1; t1.y/=l1; t1.z/=l1;
    Vec3 t2=cross3(n,t1);
    double x1=l1, y1=0.0;
    double x2=dot3(e2,t1), y2=dot3(e2,t2);
    if (y2<0){ /* keep winding */ }

    /* gradient of the linear map over the triangle */
    double d = x1*y2 - x2*y1; if (fabs(d)<1e-14) return;
    double Wtri[3][2] = { { (y2-y1)/d, (x1-x2)/d },   /* Wi = grad lambda1 */
                          {      -y2/d,        x2/d }, /* Wj = grad lambda2 */
                          {      y1/d,       -x1/d } };
    int vid[3]={i,j,k};
    /* complex weights: a = W, b = i*W  (rot90) */
    for (int a=0;a<3;a++){
      for (int b=0;b<3;b++){
        double ar=Wtri[a][0], ai=Wtri[a][1];
        double br=Wtri[b][0], bi=Wtri[b][1];
        /* contribution to normal equations for complex unknowns
           u_a, u_b :  conj(w_a) * w_b  (w = a - i*b form) */
        double cr = ar*br + ai*bi;
        double ci = ar*bi - ai*br;
        int ra=4*s->lidx[vid[a]], cb=4*s->lidx[vid[b]];
        /* real part block */
        addATA(s,ra+0,cb+0, cr); addATA(s,ra+0,cb+2, -ci);
        addATA(s,ra+2,cb+0, ci); addATA(s,ra+2,cb+2,  cr);
        /* imag part block (same structure) */
        addATA(s,ra+1,cb+1, cr); addATA(s,ra+1,cb+3, -ci);
        addATA(s,ra+3,cb+1, ci); addATA(s,ra+3,cb+3,  cr);
      }
    }
}

/* dense Cholesky solve in place, n x n symmetric positive definite */
static int cholesky(double *A,double *b,int n)
{
    for (int i=0;i<n;i++){
        for (int j=0;j<=i;j++){
            double s=A[i*n+j];
            for (int k=0;k<j;k++) s-=A[i*n+k]*A[j*n+k];
            if (i==j){
                if (s<=1e-12) return 0;
                A[i*n+i]=sqrt(s);
            } else A[i*n+j]=s/A[j*n+j];
        }
    }
    for (int i=0;i<n;i++){
        double s=b[i];
        for (int k=0;k<i;k++) s-=A[i*n+k]*b[k];
        b[i]=s/A[i*n+i];
    }
    for (int i=n-1;i>=0;i--){
        double s=b[i];
        for (int k=i+1;k<n;k++) s-=A[k*n+i]*b[k];
        b[i]=s/A[i*n+i];
    }
    return 1;
}

/* result UV per global vertex */
static double *UVu, *UVv;

static void flatten_patch(int pid, const char *outdir)
{
    /* collect vertices of this patch */
    int *vidx = malloc(nV*sizeof(int)); int n=0;
    int *lidx = malloc(nV*sizeof(int));
    for (int i=0;i<nV;i++){ lidx[i]=-1; if (vertPatch[i]==pid) { lidx[i]=n; vidx[n++]=i; } }
    if (n<3) { free(vidx); free(lidx); return; }

    LS s; s.n=n; s.vidx=vidx; s.lidx=lidx;
    int N=4*n;
    s.ATA=calloc((size_t)N*N,sizeof(double));
    s.ATb=calloc((size_t)N,sizeof(double));

    /* area weights: weight each triangle by its 3D area so that
       large triangles matter more (better area preservation).
       Set all weights to 1.0 instead for uniform treatment. */
    for (int t=0;t<nT;t++) if (triPatch[t]==pid){
        Vec3 n3=cross3(sub3(V[T[t].b],V[T[t].a]), sub3(V[T[t].c],V[T[t].a]));
        accumulate_tri(&s,t);
        /* (area weighting would scale rows; the simple unweighted
           LSCM above is already a good default) */
    }

    /* pin two well-separated vertices: vertex 0 and the vertex
       farthest from it. Pinning fixes translation, rotation, scale. */
    int far=0; double best=-1;
    for (int i=1;i<n;i++){
        Vec3 d=sub3(V[vidx[i]],V[vidx[0]]);
        double dd=dot3(d,d); if(dd>best){best=dd; far=i;}
    }
    int p0=0, p1=far;
    double d0[2]={0,0}, d1[2]={1,0};   /* target positions */

    /* move pinned contributions to RHS */
    for (int r=0;r<N;r++){
        double ar=s.ATA[r*4*0+4*p0+0], ai=s.ATA[r*4*0+4*p0+2];
        double br=s.ATA[r*4*0+4*p1+0], bi=s.ATA[r*4*0+4*p1+2];
        s.ATb[r]   -= ar*d0[0]+(-ai)*d0[1] + br*d1[0]+(-bi)*d1[1];
        s.ATb[r+1] -= ai*d0[0]+ ar*d0[1] + bi*d1[0]+ br*d1[1];
    }
    /* zero pinned rows/cols, set identity */
    for (int c=0;c<4;c++){
        int rows[4]={4*p0+c, 4*p1+c}; /* handled per-block below */
    }
    for (int k=0;k<4;k++){
        int row=4*p0+k;
        for (int c=0;c<N;c++) s.ATA[row*N+c]=0;
        for (int r=0;r<N;r++) s.ATA[r*N+row]=0;
        s.ATA[row*N+row]=1; s.ATb[row]=d0[k/2?1:0];
        row=4*p1+k;
        for (int c=0;c<N;c++) s.ATA[row*N+c]=0;
        for (int r=0;r<N;r++) s.ATA[r*N+row]=0;
        s.ATA[row*N+row]=1; s.ATb[row]=(k/2)?0.0:1.0;
    }

    double *x=malloc(N*sizeof(double));
    memcpy(x,s.ATb,N*sizeof(double));
    if (!cholesky(s.ATA,x,N)){
        fprintf(stderr,"patch %d: singular system, skipped\n",pid);
        free(x); free(s.ATA); free(s.ATb); free(vidx); free(lidx);
        return;
    }

    /* store results */
    for (int i=0;i<n;i++){
        int g=vidx[i];
        UVu[g]=x[4*i+0]; UVv[g]=x[4*i+2];
    }
    free(x); free(s.ATA); free(s.ATb); free(vidx); free(lidx);

    /* ---- write SVG page ---- */
    char path[1024]; snprintf(path,sizeof path,"%s/patch_%03d.svg",outdir,pid);
    FILE *f=fopen(path,"w");
    if(!f) return;

    /* bounds */
    double minu=1e30,maxu=-1e30,minv=1e30,maxv=-1e30;
    for (int t=0;t<nT;t++) if (triPatch[t]==pid){
        int ids[3]={T[t].a,T[t].b,T[t].c};
        for (int q=0;q<3;q++){
            double u=UVu[ids[q]], v=UVv[ids[q]];
            if(u<minu)minu=u; if(u>maxu)maxu=u;
            if(v<minv)minv=v; if(v>maxv)maxv=v;
        }
    }
    double w=maxu-minu, h=maxv-minv; if(w<1e-9)w=1; if(h<1e-9)h=1;
    double scale=900.0/(w>h?w:h);
    double ox=50-minu*scale, oy=50+maxv*scale; /* SVG y is down */

    fprintf(f,"<?xml version=\"1.0\"?>\n"
              "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1000\" height=\"1000\">\n");
    fprintf(f,"<rect width=\"1000\" height=\"1000\" fill=\"white\"/>\n");
    for (int t=0;t<nT;t++) if (triPatch[t]==pid){
        int ids[3]={T[t].a,T[t].b,T[t].c};
        fprintf(f,"<polygon points=\"");
        for (int q=0;q<3;q++)
            fprintf(f,"%.3f,%.3f ", ox+UVu[ids[q]]*scale, oy-UVv[ids[q]]*scale);
        fprintf(f,"\" fill=\"none\" stroke=\"black\" stroke-width=\"0.5\"/>\n");
    }
    fprintf(f,"</svg>\n");
    fclose(f);
    printf("patch %03d: %d verts, %d tris -> %s\n",pid,n,[^]
           ({int c=0; for(int t=0;t<nT;t++) if(triPatch[t]==pid)c++; c;}()), path);
}

int main(int argc,char **argv)
{
    if (argc<3){ fprintf(stderr,"usage: %s model.obj outdir\n",argv[0]); return 1; }
    load_obj(argv[1]);
    build_patches();
    UVu=calloc(nV,sizeof(double)); UVv=calloc(nV,sizeof(double));
    mkdir(argv[2],0755);
    printf("%d vertices, %d triangles, %d patches\n",nV,nT,nPatches);
    for (int p=0;p<nPatches;p++) flatten_patch(p,argv[2]);
    return 0;
}
```

## Notes on the design

**Why LSCM.** It solves a linear system (no iteration, no folding in practice for reasonable meshes), pins two vertices to fix translation/rotation/scale, and minimizes conformal (angle) distortion, which keeps area distortion moderate. If area fidelity matters more to you than angles, the standard alternative is ABF++ (angle-based flattening, then merge to UVs) — nonlinear, iterative, but explicitly targets angle/area balance. I'd start with LSCM and measure distortion before reaching for it.

**Patch segmentation.** I split by vertex connectivity (union-find), so each connected sheet of triangles becomes its own page. If your "surfaces" are defined differently — by material groups (`usemtl`), by sharp crease angles, or by an explicit face-group file — replace `build_patches()`; the rest is unchanged. If you have a per-triangle group ID list, that's a three-line change.

