    LS s; s.n=n;
    s.A=calloc((size_t)N*N,sizeof(double));
    s.b=calloc((size_t)N,sizeof(double));

    for (int t=0;t<nT;t++) if (triPatch[t]==pid)
        accumulate_tri(&s, lidx[T[t].a], lidx[T[t].b], lidx[T[t].c], t);

    /* pin two well-separated vertices: fixes translation, rotation, scale.
       p0 -> (0,0), p1 -> (1,0). */
    int p1=0; double best=-1;
    for (int i=1;i<n;i++){
        Vec3 d=sub3(V[vidx[i]],V[vidx[0]]);
        double dd=dot3(d,d); if(dd>best){best=dd; p1=i;}
    }
    int p0=0;

    /* move pinned unknowns' contributions to the rhs (p0 target is 0) */
    for (int r=0;r<N;r++)
        s.b[r] -= s.A[(size_t)r*N + 2*p1+0]*1.0;

    for (int kk=0;kk<2;kk++){
        int rows[2]={2*p0+kk, 2*p1+kk};
        double tgt[2]={0.0, 1.0};
        for (int q=0;q<2;q++){
            int row=rows[q];
            for (int c=0;c<N;c++) s.A[(size_t)row*N+c]=0;
            for (int r=0;r<N;r++) s.A[(size_t)r*N+row]=0;
            s.A[(size_t)row*N+row]=1;
            s.b[row]=tgt[q];
        }
    }

    double *x=malloc(N*sizeof(double));
    memcpy(x,s.b,N*sizeof(double));
    if (!cholesky(s.A,x,N)){
        fprintf(stderr,"patch %d: singular system, skipped\n",pid);
        free(x); free(s.A); free(s.b); free(vidx); free(lidx);
        return;
    }

    for (int i=0;i<n;i++){ UVu[vidx[i]]=x[2*i]; UVv[vidx[i]]=x[2*i+1]; }
    free(x); free(s.A); free(s.b);

    /* ---- write SVG page ---- */
    char path[1024]; snprintf(path,sizeof path,"%s/patch_%03d.svg",outdir,pid);
    FILE *f=fopen(path,"w");
    if(!f){ free(vidx); free(lidx); return; }

    double minu=1e30,maxu=-1e30,minv=1e30,maxv=-1e30;
    for (int t=0;t<nT;t++) if (triPatch[t]==pid){
        int ids[3]={T[t].a,T[t].b,T[t].c};
        for (int q=0;q<3;q++){
            double u=UVu[ids[q]], v=UVv[ids[q]];
            if(u<minu)minu=u; if(u>maxu)maxu=u;
            if(v<minv)minv=v; if(v>maxv)maxv=v;
        }
    }
    double w=maxu-minu, h=maxv-minv; if(w<1e-9)w=1; if(h<1e-9)h=1;
    double scale=900.0/(w>h?w:h);
    double ox=50-minu*scale, oy=50+maxv*scale;   /* SVG y grows downward */

    fprintf(f,"<?xml version=\"1.0\"?>\n"
              "<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"1000\" height=\"1000\">\n");
    fprintf(f,"<rect width=\"1000\" height=\"1000\" fill=\"white\"/>\n");
    for (int t=0;t<nT;t++) if (triPatch[t]==pid){
        int ids[3]={T[t].a,T[t].b,T[t].c};
        fprintf(f,"<polygon points=\"");
        for (int q=0;q<3;q++)
            fprintf(f,"%.3f,%.3f ", ox+UVu[ids[q]]*scale, oy-UVv[ids[q]]*scale);
        fprintf(f,"\" fill=\"none\" stroke=\"black\" stroke-width=\"0.5\"/>\n");
    }
    fprintf(f,"</svg>\n");
    fclose(f);
    printf("patch %03d: %d verts, %d tris -> %s\n",pid,n,ntri,path);

    free(vidx); free(lidx);
}

int main(int argc,char **argv)
{
    if (argc<3){ fprintf(stderr,"usage: %s model.obj outdir\n",argv[0]); return 1; }
    load_obj(argv[1]);
    build_patches();
    UVu=calloc(nV,sizeof(double)); UVv=calloc(nV,sizeof(double));
    mkdir(argv[2],0755);
    printf("%d vertices, %d triangles, %d patches\n",nV,nT,nPatches);
    for (int p=0;p<nPatches;p++) flatten_patch(p,argv[2]);
    return 0;
}
